engine.py.text:
"""Review engine of TASK-20261002-ed5777 (red team, J3). An independent numpy
replica, IN LAW, of the committed pair stream, label cache, bucket gain,
shuffles and nulls of CODE-EST, on permitted groups only (declared_groups_rule).
Decisions are NOT re-implemented here: every clause is evaluated by the
committed estimator functions (est.seed_rows, est.clause_L1, est.clause_L2,
est.clause_L3, est.classify_family) imported from the extracted, pin-checked
CODE-EST. Import executes nothing.
"""
import math
import sys
import zlib

import numpy as np

MIN_CELL = 100
EXCLUDED_PRIMES = (2003, 130873, 2095853, 549756390943, 261823, 32603, 137, 239)


def check_permitted(N):
    for p in EXCLUDED_PRIMES:
        if N % p == 0:
            raise ValueError("excluded order %d (divisible by %d)" % (N, p))
    if N == (1 << 17):
        raise ValueError("Z/2^17 excluded")
    return N


def seed32(*parts):
    return zlib.crc32(("ed5777:" + ":".join(str(p) for p in parts)).encode("ascii"))


def S_of(M):
    return 1 << (128 * M * M - 1).bit_length()


class Stream:
    """S ordered pairs (P, Q, P + Q) on Z/N, P and Q uniform on 1..N-1, a pair
    whose sum is the identity redrawn (the committed ZCell / IsoCell law).
    pts[k] = (P, Q, R). support(Sp) gives the distinct points of the first Sp
    pairs and the index triples into them."""

    def __init__(self, N, S, rng):
        check_permitted(N)
        self.N, self.S = N, S
        P = rng.integers(1, N, size=S, dtype=np.int64)
        Q = rng.integers(1, N, size=S, dtype=np.int64)
        R = (P + Q) % N
        bad = R == 0
        while bad.any():
            k = int(bad.sum())
            P[bad] = rng.integers(1, N, size=k, dtype=np.int64)
            Q[bad] = rng.integers(1, N, size=k, dtype=np.int64)
            R[bad] = (P[bad] + Q[bad]) % N
            bad = R == 0
        self.pts = np.stack([P, Q, R], axis=1)
        self._sup = {}

    def support(self, Sp):
        if Sp not in self._sup:
            flat = self.pts[:Sp].ravel()
            uniq, inv = np.unique(flat, return_inverse=True)
            self._sup[Sp] = (uniq, inv.reshape(Sp, 3).astype(np.int32))
        return self._sup[Sp]


def gain(inv, lab, M):
    """est.gain in law AND in arithmetic: G = M x max over used cells (n_ab >=
    MIN_CELL) of max_c n_abc / n_ab, with used, excluded, empty, used_mass,
    point_mass_used, S."""
    lab = lab.astype(np.int32, copy=False)
    cnt = np.bincount((lab[inv[:, 0]] * M + lab[inv[:, 1]]) * M + lab[inv[:, 2]],
                      minlength=M * M * M).reshape(M * M, M)
    nab = cnt.sum(axis=1)
    usedm = nab >= MIN_CELL
    used = int(usedm.sum())
    excluded = int(((nab > 0) & (nab < MIN_CELL)).sum())
    empty = int((nab == 0).sum())
    if used:
        top = cnt[usedm].max(axis=1)
        nu = nab[usedm]
        ratios = top / nu
        best = float(ratios.max())
        pm = int((top == nu).sum())
        umass = int(nu.sum())
    else:
        best, pm, umass = 0.0, 0, 0
    return {"G": M * best, "used": used, "excluded": excluded, "empty": empty,
            "used_mass": umass, "point_mass_used": pm, "S": int(inv.shape[0])}


def used_cell_image(inv, lab, M):
    """families.used_cell_image in law: labels a, b of used cells and every c seen in them."""
    a = lab[inv[:, 0]].astype(np.int64)
    b = lab[inv[:, 1]].astype(np.int64)
    c = lab[inv[:, 2]].astype(np.int64)
    ab = a * M + b
    nab = np.bincount(ab, minlength=M * M)
    keep = nab[ab] >= MIN_CELL
    seen = set(np.unique(a[keep]).tolist()) | set(np.unique(b[keep]).tolist()) | set(np.unique(c[keep]).tolist())
    return sorted(seen)


def strat_perm(strata, rng):
    """One within-stratum permutation of support positions (identity on the
    stratum structure); strata None -> one global permutation."""
    U = len(strata) if strata is not None else None
    if strata is None:
        raise ValueError("use global_perm")
    perm = np.arange(U)
    for s in np.unique(strata):
        idx = np.flatnonzero(strata == s)
        perm[idx] = idx[rng.permutation(len(idx))]
    return perm


def global_perm(U, rng):
    return rng.permutation(U)


def uniform_labels(U, M, rng):
    return rng.integers(0, M, size=U).astype(np.int64)


def saturated_labels(strata, M, q, rng):
    return q * rng.integers(0, M // q, size=len(strata)).astype(np.int64) + strata


def skewed_residual(m, size, rng):
    """estimator.skewed_residual in law: 0 w.p. 1/2, else uniform on 1..m-1."""
    z = rng.random(size) < 0.5
    r = 1 + rng.integers(0, max(m - 1, 1), size=size)
    return np.where(z, 0, r).astype(np.int64)


def xco2_labels(strata, M, q, rng):
    return q * skewed_residual(M // q, len(strata), rng) + strata


def weight_buckets(n, M):
    tot = float(2 ** n)
    out, acc = [], 0
    for w in range(n + 1):
        pw = math.comb(n, w)
        out.append(min(M - 1, int(math.floor(M * (acc + pw / 2.0) / tot))))
        acc += pw
    return np.array(out, dtype=np.int64)


def xco1_labels(strata, n, M, rng):
    """estimator.exact_content_x1 in law: w ~ Binomial(n, 1/2) conditioned on
    w = e (mod 2), label wb[w]."""
    wb = weight_buckets(n, M)
    U = len(strata)
    bit = (strata & 1).astype(np.int64)
    w = rng.binomial(n, 0.5, size=U)
    badm = (w & 1) != bit
    while badm.any():
        k = int(badm.sum())
        w[badm] = rng.binomial(n, 0.5, size=k)
        badm = (w & 1) != bit
    return wb[w]


def planted_marginal(U, M, rng):
    z = rng.random(U) < 0.5
    return np.where(z, 0, 1 + rng.integers(0, M - 1, size=U)).astype(np.int64)


def planted_mixture(lab, M, rho, rng):
    keep = rng.random(len(lab)) < rho
    return np.where(keep, lab, rng.integers(0, M, size=len(lab))).astype(np.int64)


def key_labels(points, l, M):
    """floor((i mod l) M / l), the log-interval key of the l-component."""
    return (((points % l) * M) // l).astype(np.int64)


def quantile(vals, p):
    s = sorted(vals)
    k = max(1, int(math.ceil(p * len(s) - 1e-9)))
    return s[k - 1]


def median(vals):
    s = sorted(vals)
    n = len(s)
    if n % 2:
        return s[n // 2]
    return 0.5 * (s[n // 2 - 1] + s[n // 2])


def reading(inv, lab, M, perms):
    d = gain(inv, lab, M)
    sh = [gain(inv, lab[p], M)["G"] for p in perms]
    return {"direct": d, "shuffle": sh}

rules.py.text:
"""Bridge from the review engine's per-seed records to the COMMITTED decision
code: every clause below is the frozen CODE-EST function (est.summarize_null,
est.seed_rows, est.clause_L1, est.clause_L2, est.clause_L3, est.estimated,
est.classify_family) imported from the pin-checked extraction in impl/."""
import json
import math
import sys

import numpy as np

sys.path.insert(0, "impl")
import estimator as est  # noqa: E402


def load(path, key=("seed", "M")):
    recs = {}
    for line in open(path):
        try:
            r = json.loads(line)
        except ValueError:
            continue  # a line truncated by a stopped process is skipped, never repaired
        recs.setdefault(r["M"], {})[r["seed"]] = r
    return recs


def load_many(paths):
    out = {}
    for p in paths:
        try:
            for M, d in load(p).items():
                out.setdefault(M, {}).update(d)
        except FileNotFoundError:
            pass
    return out


def cell(recs, name):
    """est-compatible {rows, null} for one label over the given seed records."""
    by_seed = [[{"G": g} for g in r["null"]] for r in recs]
    ns = est.summarize_null(by_seed)
    readings = []
    for r in recs:
        d = r["labels"][name]
        readings.append({"direct": {"G": d["G"], "used": d["used"], "excluded": d["excluded"],
                                    "used_mass": d["used_mass"], "S": d["S"]},
                         "shuffle": d["sh"]})
    rows = est.seed_rows(readings, ns, ns["V"])
    return {"rows": rows, "null": ns}


def ir2_invalid(ns):
    return not (ns["W"] > 0 and all(v > 0 for v in ns["V"]))


def seed_Z(r, name):
    """Per-seed Z = E_Sh / V_s with the seed's own width (est.seed_width)."""
    vals = sorted(r["null"])
    v = est.quantile(vals, 0.90) - est.quantile(vals, 0.50)
    d = r["labels"][name]
    e_sh = d["G"] - est.median(d["sh"])
    return (e_sh / v) if v > 0 else None


def slope_weights(xs):
    xs = np.asarray(xs, dtype=float)
    xm = xs.mean()
    sxx = ((xs - xm) ** 2).sum()
    return (xs - xm) / sxx


def p_slope_nonneg(z1, z2, z3, xs):
    """Exact P(OLS slope >= 0) for independent draws Z_i from the three pools
    (uniform over pool members): slope = sum w_i Z_i with sum w_i = 0."""
    w = slope_weights(xs)
    a = (w[0] * np.asarray(z1, dtype=float))[:, None] + (w[1] * np.asarray(z2, dtype=float))[None, :]
    a = a.ravel()
    c = np.sort(w[2] * np.asarray(z3, dtype=float))
    # count pairs with a + c >= 0  <=>  c >= -a
    idx = np.searchsorted(c, -a, side="left")
    good = (len(c) - idx).sum()
    return good / float(len(a) * len(c))


def l2_fail_prob(p):
    """L2 fails when at most one of ten i.i.d. per-seed slopes is >= 0."""
    return (1 - p) ** 10 + 10 * p * (1 - p) ** 9


def binom_upper(k, n, conf=0.95):
    """One-sided Clopper-Pearson upper bound for k events in n trials."""
    if k >= n:
        return 1.0
    lo, hi = k / n, 1.0
    lgn = math.lgamma(n + 1)
    for _ in range(80):
        mid = (lo + hi) / 2
        # P(X <= k | p = mid), summed in log space
        lp, lq = math.log(mid), math.log1p(-mid)
        cdf = sum(math.exp(lgn - math.lgamma(i + 1) - math.lgamma(n - i + 1) + i * lp + (n - i) * lq)
                  for i in range(k + 1))
        if cdf > 1 - conf:
            lo = mid
        else:
            hi = mid
    return hi

analyze_zl.py.text:
"""Analysis of Part A: PC-7, PC-7c, PC-16, PC-16b, PC-16c on the permitted
Z/l' ladder, through the committed CODE-EST clauses. Runs of ten seeds are
formed by sampling seeds without replacement from each prime's pool
(independently across primes, as the three cells are independent).
Usage: analyze_zl.py RUNS SEED OUT"""
import json
import math
import sys

import numpy as np

import rules as R
from rules import est

PRIMES = (1999, 130859, 2095837)
ALPH = {1999: (16, 8), 130859: (64, 16), 2095837: (128, 32, 16)}
LEAD = {1999: 16, 130859: 64, 2095837: 128}
DECAY_NAME = {1999: "key", 130859: "decay", 2095837: "decay"}
FILES = {1999: ["out/zl0.jsonl"], 130859: ["out/zl1.jsonl"],
         2095837: ["out/zl2_a.jsonl", "out/zl2_b.jsonl"]}


def main(runs, seed, out):
    pools = {l: R.load_many(FILES[l]) for l in PRIMES}
    seeds = {l: sorted(set.intersection(*[set(pools[l][M]) for M in ALPH[l]])) for l in PRIMES}
    xs = [math.log2(l) for l in PRIMES]
    rng = np.random.default_rng(seed)
    fails = {"PC-7": 0, "PC-7c": 0, "PC-16": 0, "PC-16b": 0, "PC-16c": 0, "zero_width": 0}
    detail = {"PC-7": {}, "PC-7c": {}}
    margins = {}
    for t in range(runs):
        pick = {l: rng.choice(seeds[l], size=10, replace=False) for l in PRIMES}
        key_cells, flat_cells, decay_cells = {}, {}, {}
        f7 = f7c = False
        for l in PRIMES:
            for M in ALPH[l]:
                recs = [pools[l][M][int(s)] for s in pick[l]]
                ck = R.cell(recs, "key")
                ns, rows = ck["null"], ck["rows"]
                if R.ir2_invalid(ns):
                    fails["zero_width"] += 1
                gk = est.median([r["G"] for r in rows])
                l1, l3 = est.clause_L1(rows, ns), est.clause_L3(rows, ns)
                ok7 = gk >= M / 3.0 and gk < M and l1 and l3
                mk = "%d@%d" % (l, M)
                m = margins.setdefault(mk, {"E_RL_over_W": [], "E_Sh_over_W": [], "G_over_M": [],
                                            "rank_floor_hits": [], "win_rank_floor_max": [],
                                            "win_E_Sh_over_W_max": []})
                if ns["W"] > 0:
                    m["E_RL_over_W"].append(est.median([r["E_RL"] for r in rows]) / ns["W"])
                    m["E_Sh_over_W"].append(est.median([r["E_Sh"] for r in rows]) / ns["W"])
                m["G_over_M"].append(gk / M)
                m["rank_floor_hits"].append(sum(1 for r in rows if r["p"] <= 1 / 11 + 1e-12))
                if not ok7:
                    f7 = True
                    detail["PC-7"][mk] = detail["PC-7"].get(mk, 0) + 1
                wmax, wesh = 0, -1e9
                for name in recs[0]["labels"]:
                    if name.startswith("win@"):
                        cw = R.cell(recs, name)
                        hits = sum(1 for r in cw["rows"] if r["p"] <= 1 / 11 + 1e-12)
                        wmax = max(wmax, hits)
                        if ns["W"] > 0:
                            wesh = max(wesh, est.median([r["E_Sh"] for r in cw["rows"]]) / ns["W"])
                        if est.clause_L3(cw["rows"], cw["null"]):
                            f7c = True
                            detail["PC-7c"][mk] = detail["PC-7c"].get(mk, 0) + 1
                m["win_rank_floor_max"].append(wmax)
                m["win_E_Sh_over_W_max"].append(wesh)
                if M == LEAD[l]:
                    key_cells[("Z-%d" % l, M)] = ck
                if M == 16:
                    flat_cells[("Z-%d" % l, M)] = ck
                    decay_cells[("Z-%d" % l, M)] = R.cell(recs, DECAY_NAME[l])
        fails["PC-7"] += f7
        fails["PC-7c"] += f7c
        lead = est.classify_family(key_cells, [("Z-%d" % l, LEAD[l]) for l in PRIMES], xs)
        flat = est.classify_family(flat_cells, [("Z-%d" % l, 16) for l in PRIMES], xs)
        dec = est.classify_family(decay_cells, [("Z-%d" % l, 16) for l in PRIMES], xs)
        fails["PC-16"] += not (lead["verdict"] == "LEAD")
        fails["PC-16b"] += not (flat["verdict"] == "LEAD")
        fails["PC-16c"] += dec["verdict"] == "LEAD"
    # exact per-seed slope-sign probabilities over all seed triples
    zp = {}
    for tag, (names, Ms) in {"PC-16 key at lead alphabets": (("key", "key", "key"), (16, 64, 128)),
                             "PC-16b key at M = 16": (("key", "key", "key"), (16, 16, 16)),
                             "PC-16c decay at M = 16": (("key", "decay", "decay"), (16, 16, 16))}.items():
        zs = []
        for l, nm, M in zip(PRIMES, names, Ms):
            zs.append([R.seed_Z(pools[l][M][s], nm) for s in seeds[l]])
        p = R.p_slope_nonneg(*zs, xs)
        zp[tag] = {"p_seed_slope_nonneg": p, "run_L2_fail_prob": R.l2_fail_prob(p),
                   "run_L2_hold_prob": 1 - R.l2_fail_prob(p),
                   "pool_sizes": [len(z) for z in zs],
                   "Z_median_per_cell": [float(np.median(z)) for z in zs],
                   "Z_sd_per_cell": [float(np.std(z)) for z in zs]}
    summ = {}
    for mk, m in margins.items():
        summ[mk] = {k: {"min": float(np.min(v)), "p01": float(np.percentile(v, 1)),
                        "median": float(np.median(v)), "max": float(np.max(v))}
                    for k, v in m.items() if len(v)}
    res = {"runs": runs, "resample_seed": seed, "pool_seeds": {l: len(seeds[l]) for l in PRIMES},
           "run_failures": fails,
           "run_failure_rate": {k: v / runs for k, v in fails.items()},
           "run_failure_upper95": {k: R.binom_upper(v, runs) for k, v in fails.items()},
           "failure_detail": detail, "L2_exact": zp, "margins": summ}
    json.dump(res, open(out, "w"), indent=1, default=float)
    print(json.dumps({k: res[k] for k in ("pool_seeds", "run_failures", "run_failure_upper95", "L2_exact")},
                     indent=1, default=float))


if __name__ == "__main__":
    main(int(sys.argv[1]), int(sys.argv[2]), sys.argv[3])

analyze_iso.py.text:
"""Analysis of Parts B and C through the COMMITTED decision code (CODE-EST
clauses, families.stage3, families.sr6_check, exact_content.pc17_cell,
degeneracy.classify). Synthetic per-seed statistics from the permitted groups
Z/(q l') are keyed by declared cell and role NAMES only where the committed
stage3 needs them (the plan's name-grid carve-out); no element of an excluded
group is constructed. Usage: analyze_iso.py RUNS SEED OUT"""
import json
import math
import sys

import numpy as np

import rules as R
from rules import est
import families as fam
import exact_content as xco
import degeneracy as degen

FILES = {"K13": ["out/iso_K13.jsonl"], "K19": ["out/iso_K19.jsonl"],
         "K23": ["out/iso_K23_a.jsonl", "out/iso_K23_b.jsonl", "out/iso_K23_c.jsonl"],
         "K41": ["out/iso_K41.jsonl"], "O19": ["out/iso_O19.jsonl"]}
ALPH = {"K13": (16, 8), "K19": (64, 16), "K23": (128, 32, 16), "K41": (16,), "O19": (64, 16)}
LPRIME = {"K13": 1999, "K19": 130859, "K23": 2095837, "K41": 549756390899, "O19": 261799}
NAME = {"K13": "CELL-K13", "K19": "CELL-K19", "K23": "CELL-K23", "K41": "CELL-K41", "O19": "CELL-O19"}
LEADS = (("K13", 16), ("K19", 64), ("K23", 128))
KOB_KEYS = (("K13", 16), ("K13", 8), ("K19", 64), ("K19", 16), ("K23", 128), ("K23", 32),
            ("K23", 16), ("K41", 16))
ORD_KEYS = (("O19", 64), ("O19", 16))
STATED_XF_FLOOR = {("K13", 16): 0.7, ("K19", 64): 0.5, ("K23", 128): 0.5}
STATED_XC_FLOOR = {("K13", 16): 0.9, ("K19", 64): 0.6, ("K23", 128): 0.5}
XF_RHOS = (1.0, 0.9, 0.8, 0.7, 0.6, 0.5, 0.4)
XC_RHOS = (1.0, 0.9, 0.8, 0.6, 0.5)
NULL_LABELS = ("RLFAM", "XCO1", "XCO2", "PTME1", "CONC", "NEAR1", "NEAR2", "NEAR3", "NEARMASS")
ROLE_SOURCE = {"F1": "XCO1", "F2@0": "RLFAM", "F2@mid": "RLFAM", "F2@end": "RLFAM",
               "F3@0": "RLFAM", "F3@mid": "RLFAM", "F3@end": "RLFAM", "F4": "RLFAM",
               "F5xF1": "XCO2", "F5xF2@0": "XCO2", "F5xF3@0": "XCO2", "F5xF4": "CONC"}


def cellns(recs, name, ns):
    readings = []
    for r in recs:
        d = r["labels"][name]
        readings.append({"direct": {"G": d["G"], "used": d["used"], "excluded": d["excluded"],
                                    "used_mass": d["used_mass"], "S": d["S"]}, "shuffle": d["sh"]})
    return {"rows": est.seed_rows(readings, ns, ns["V"]), "null": ns}


def nullsum(recs):
    return est.summarize_null([[{"G": g} for g in r["null"]] for r in recs])


def stats(v):
    v = [x for x in v if x is not None]
    if not v:
        return None
    return {"n": len(v), "min": float(np.min(v)), "p05": float(np.percentile(v, 5)),
            "median": float(np.median(v)), "p95": float(np.percentile(v, 95)), "max": float(np.max(v))}


def main(runs, seed, out):
    pools = {sh: R.load_many(FILES[sh]) for sh in FILES}
    seeds = {sh: sorted(set.intersection(*[set(pools[sh][M]) for M in ALPH[sh]])) for sh in FILES}
    xs = [math.log2(LPRIME[s]) for s, _ in LEADS]
    rng = np.random.default_rng(seed)
    cnt = {"PC-16d_fail": 0, "PC-16d_XF_fail": 0, "PC-16d_XC_fail": 0, "PC-18_fail": 0,
           "PC-17_fail_any_cell": 0, "stage3_voided": 0, "stage3_not_all_NEG": 0,
           "PC-15_fail": 0, "SR6_fired": 0, "ir2_invalid_any": 0, "heurb2_falsified_any": 0}
    l3_events, est_fail, l1_hold = {}, {}, {}
    floor_hist = {"XF": {}, "XC": {}}
    l3_by_rho = {}
    verdict_counts = {}
    pc16d_detail = {"XF": {"L1": {}, "L3": {}, "L2": 0}, "XC": {"L1": {}, "L3": {}, "L2": 0}}
    margins = {}
    ptm = {"PTM-E": {}, "PTM-F": {}}
    for t in range(runs):
        pick = {sh: [int(s) for s in rng.choice(seeds[sh], size=10, replace=False)] for sh in FILES}
        recs = {(sh, M): [pools[sh][M][s] for s in pick[sh]] for sh in FILES for M in ALPH[sh]}
        nss = {k: nullsum(v) for k, v in recs.items()}
        if any(R.ir2_invalid(ns) for ns in nss.values()):
            cnt["ir2_invalid_any"] += 1
        cells = {}
        for k, v in recs.items():
            for name in v[0]["labels"]:
                cells[(k, name)] = cellns(v, name, nss[k])
        # PC-16d
        ok = {}
        for cls in ("XF", "XC"):
            cm = {(LEADS[i][0], LEADS[i][1]): cells[(LEADS[i], cls + "@1")] for i in range(3)}
            v = est.classify_family(cm, list(cm.keys()), xs)
            ok[cls] = v["verdict"] == "LEAD"
            for kk, p in v["per_cell"].items():
                tag = "%s@%d" % kk
                pc16d_detail[cls]["L1"][tag] = pc16d_detail[cls]["L1"].get(tag, 0) + (not p["L1"])
                pc16d_detail[cls]["L3"][tag] = pc16d_detail[cls]["L3"].get(tag, 0) + (not p["L3"])
            if v["L2"] is not None and not v["L2"]["holds"]:
                pc16d_detail[cls]["L2"] += 1
            for kk in cm:
                rows, ns = cm[kk]["rows"], cm[kk]["null"]
                mg = margins.setdefault("%s(1)@%s@%d" % (cls, kk[0], kk[1]), {"E_RL_W": [], "E_Sh_W": []})
                mg["E_RL_W"].append(est.median([r["E_RL"] for r in rows]) / ns["W"])
                mg["E_Sh_W"].append(est.median([r["E_Sh"] for r in rows]) / ns["W"])
        cnt["PC-16d_XF_fail"] += not ok["XF"]
        cnt["PC-16d_XC_fail"] += not ok["XC"]
        cnt["PC-16d_fail"] += not (ok["XF"] and ok["XC"])
        # NEG-path floors (own) at the lead keys
        for k in LEADS:
            for cls, rhos in (("XF", XF_RHOS), ("XC", XC_RHOS)):
                l3s = {}
                for rho in sorted(rhos, reverse=True):
                    c = cells[(k, "%s@%g" % (cls, rho))]
                    l3 = bool(est.estimated(c["rows"]) and est.clause_L3(c["rows"], c["null"]))
                    l3s[rho] = l3
                    key = "%s@%d/%s@%g" % (k[0], k[1], cls, rho)
                    l3_by_rho[key] = l3_by_rho.get(key, 0) + l3
                    mg = margins.setdefault(key, {"E_Sh_W": [], "E_RL_W": []})
                    mg["E_Sh_W"].append(est.median([r["E_Sh"] for r in c["rows"]]) / c["null"]["W"])
                    mg["E_RL_W"].append(est.median([r["E_RL"] for r in c["rows"]]) / c["null"]["W"])
                fl = None
                for rho in sorted(rhos, reverse=True):
                    if not l3s[rho]:
                        break
                    fl = rho
                tag = "%s@%d" % k
                floor_hist[cls].setdefault(tag, {})
                fk = "none" if fl is None else "%g" % fl
                floor_hist[cls][tag][fk] = floor_hist[cls][tag].get(fk, 0) + 1
        # null labels: L3 false-fire, estimated, L1 (reported), per key
        for k in KOB_KEYS + ORD_KEYS:
            for name in NULL_LABELS:
                if (k, name) not in cells:
                    continue
                c = cells[(k, name)]
                tag = "%s@%d/%s" % (k[0], k[1], name)
                e_ok = est.estimated(c["rows"])
                est_fail[tag] = est_fail.get(tag, 0) + (not e_ok)
                l3_events[tag] = l3_events.get(tag, 0) + (e_ok and est.clause_L3(c["rows"], c["null"]))
                l1_hold[tag] = l1_hold.get(tag, 0) + (e_ok and est.clause_L1(c["rows"], c["null"]))
        # Stage 2 outs keyed by declared names, for the committed stage3 / sr6_check / pc17_cell
        outs = {}
        for (sh, M), v in recs.items():
            cid = NAME[sh]
            o = outs.setdefault(cid, {})
            names = list(v[0]["labels"])
            def entry(src):
                c = cells[((sh, M), src)]
                uis = [r["labels"][src].get("used_image") for r in v]
                return {"rows": c["rows"], "null": c["null"], "image_sizes": [r["labels"][src]["image"] for r in v],
                        "used_cell_images": uis, "ir2_invalid": R.ir2_invalid(c["null"])}
            if sh == "O19":
                for role in fam.ORDINARY_ROLES:
                    o[(role, M)] = entry("RLFAM")
            else:
                for role in fam.KOBLITZ_ROLES:
                    src = ROLE_SOURCE[role]
                    if src == "CONC" and "CONC" not in names:
                        src = "NEAR2"
                    o[(role, M)] = entry(src)
            for h in fam.HELD_OUT_NAMES:
                o[(h, M)] = entry(h)
        pc17 = {cid: xco.pc17_cell(o) for cid, o in outs.items()}
        if not all(r["passed"] for r in pc17.values()):
            cnt["PC-17_fail_any_cell"] += 1
        s3 = fam.stage3(outs, xs, pc17=pc17, dropped=(), lead_guard_passed=True)
        if s3["voided"]:
            cnt["stage3_voided"] += 1
        if not s3["PC-15"]:
            cnt["PC-15_fail"] += 1
        if any(v["verdict"] != "NEG" for v in s3["verdicts"].values()):
            cnt["stage3_not_all_NEG"] += 1
        for role, v in s3["verdicts"].items():
            vc = verdict_counts.setdefault(role, {})
            vc[v["verdict"]] = vc.get(v["verdict"], 0) + 1
        if any(r[tg]["falsified"] for r in s3["heur_b2_held_out"].values() for tg in r):
            cnt["heurb2_falsified_any"] += 1
        # SR-6 on every null and near-exact label, with NO exemption table (strictest)
        sr_outs = {}
        for (sh, M), v in recs.items():
            for name in v[0]["labels"]:
                if name in NULL_LABELS:
                    sr_outs.setdefault(NAME[sh], {})[(name, M)] = {
                        "used_cell_images": [r["labels"][name].get("used_image") for r in v]}
        if fam.sr6_check(sr_outs, degeneracy=None)["fired"]:
            cnt["SR6_fired"] += 1
        # PC-18 (ISO shapes = these synthetic shapes): XCO1, XCO2 L3 nowhere and classify NEG over leads
        f18 = False
        for name in ("XCO1", "XCO2"):
            cm = {}
            for k in KOB_KEYS + ORD_KEYS:
                c = cells[(k, name)]
                if est.estimated(c["rows"]) and est.clause_L3(c["rows"], c["null"]):
                    f18 = True
                cm[k] = c
            v = est.classify_family(cm, list(LEADS), xs)
            if v["verdict"] != "NEG":
                f18 = True
        cnt["PC-18_fail"] += f18
        # PTM-E: PTME1 and XCO2 classified as family arms over the Koblitz keys
        for name in ("PTME1", "XCO2"):
            cm = {k: cells[(k, name)] for k in KOB_KEYS}
            v = est.classify_family(cm, list(LEADS), xs)["verdict"]
            ptm["PTM-E"].setdefault(name, {})
            ptm["PTM-E"][name][v] = ptm["PTM-E"][name].get(v, 0) + 1
        # PTM-F: near-exact labels classified over the Koblitz keys (NEAR2 everywhere), and at K13 alone
        cm = {k: cells[(k, "NEAR2")] for k in KOB_KEYS}
        v = est.classify_family(cm, list(LEADS), xs)["verdict"]
        ptm["PTM-F"].setdefault("NEAR2 all Koblitz keys", {})
        ptm["PTM-F"]["NEAR2 all Koblitz keys"][v] = ptm["PTM-F"]["NEAR2 all Koblitz keys"].get(v, 0) + 1
        for nm in ("NEAR1", "NEAR2", "NEAR3"):
            for M in (16, 8):
                c = cells[(("K13", M), nm)]
                ok3 = est.estimated(c["rows"]) and est.clause_L3(c["rows"], c["null"])
                tg = "%s K13@%d L3" % (nm, M)
                ptm["PTM-F"][tg] = ptm["PTM-F"].get(tg, 0) + ok3
    # exact L2 for PC-16d from per-seed pools
    l2 = {}
    for cls in ("XF", "XC"):
        zs = [[R.seed_Z(pools[sh][M][s], cls + "@1") for s in seeds[sh]] for sh, M in LEADS]
        p = R.p_slope_nonneg(*zs, xs)
        l2[cls] = {"p_seed_slope_nonneg": p, "run_L2_fail_prob": R.l2_fail_prob(p),
                   "Z_median": [float(np.median(z)) for z in zs]}
    # per-seed rank-floor probability of null labels (exchangeability check) and IR-12 mass
    seedlevel = {}
    for sh in FILES:
        for M in ALPH[sh]:
            for name in NULL_LABELS:
                rs = [pools[sh][M][s] for s in seeds[sh] if name in pools[sh][M][s]["labels"]]
                if not rs:
                    continue
                fl = [1 if all(x < r["labels"][name]["G"] for x in r["labels"][name]["sh"]) else 0 for r in rs]
                pf = float(np.mean(fl))
                tail = sum(math.comb(10, k) * pf ** k * (1 - pf) ** (10 - k) for k in range(8, 11))
                seedlevel["%s@%d/%s" % (sh, M, name)] = {
                    "seeds": len(rs), "p_rank_floor": pf, "P_ge8_of_10": tail,
                    "min_used_mass_frac": float(min(r["labels"][name]["used_mass"] / r["labels"][name]["S"] for r in rs)),
                    "exact_readings": int(sum(1 for r in rs if "used_image" in r["labels"][name])),
                    "used_images_seen": sorted(set(len(r["labels"][name]["used_image"]) for r in rs
                                                   if "used_image" in r["labels"][name]))}
    # reachability bound for the F5xF4-like label: best case G = M, so E_Sh <= M - shuffle median
    reach = {}
    for sh, M in LEADS + (("K19", 16), ("K23", 32), ("K23", 16), ("K41", 16)):
        rs = [pools[sh][M][s] for s in seeds[sh] if "CONC" in pools[sh][M][s]["labels"]]
        if not rs:
            continue
        shm = [est.median(r["labels"]["CONC"]["sh"]) for r in rs]
        Wpool = []
        for _ in range(200):
            idx = rng.choice(len(rs), size=10, replace=False)
            ns = nullsum([rs[i] for i in idx])
            Wpool.append((M - est.median([shm[i] for i in idx])) / ns["W"])
        reach["%s@%d" % (sh, M)] = {"max_attainable_median_E_Sh_over_W": stats(Wpool),
                                    "L3_needs": 3.0, "reachable": bool(np.max(Wpool) >= 3.0)}
    # PTM-F degeneracy rule on the synthetic groups (committed degeneracy.classify)
    degen_rows = {}
    for k in (1, 2, 3):
        N1 = 4 * 1999 - 1
        degen_rows["NEAR%d on Z/(4 x 1999)" % k] = degen.classify(k, N1)
    degen_rows["NEARMASS 0.0076"] = degen.classify(int(0.0076 * 1e6), 10 ** 6)
    degen_rows["NEARMASS 1.7e-4"] = degen.classify(170, 10 ** 6)
    degen_rows["CONC K13@16 (6.36 percent)"] = degen.classify(636, 10 ** 4)
    degen_rows["CONC K19@16 (1.78 percent)"] = degen.classify(178, 10 ** 4)
    res = {"runs": runs, "resample_seed": seed, "pool_seeds": {k: len(v) for k, v in seeds.items()},
           "counts": cnt, "upper95": {k: R.binom_upper(v, runs) for k, v in cnt.items()},
           "pc16d_detail": pc16d_detail, "pc16d_L2_exact": l2,
           "own_neg_path_floor_hist": floor_hist, "L3_rate_by_rho": {k: v / runs for k, v in l3_by_rho.items()},
           "margins": {k: {kk: stats(vv) for kk, vv in v.items()} for k, v in margins.items()},
           "null_label_L3_events": l3_events, "null_label_not_estimated": est_fail,
           "null_label_L1_holds": l1_hold, "seed_level": seedlevel,
           "stage3_verdict_counts": verdict_counts, "ptm": ptm, "reachability_F5xF4_like": reach,
           "degeneracy_rule_on_ptm_f": degen_rows}
    json.dump(res, open(out, "w"), indent=1, default=float)
    print(json.dumps({k: res[k] for k in ("pool_seeds", "counts", "upper95", "pc16d_L2_exact",
                                          "own_neg_path_floor_hist", "reachability_F5xF4_like", "ptm")},
                     indent=1, default=float))


if __name__ == "__main__":
    main(int(sys.argv[1]), int(sys.argv[2]), sys.argv[3])

analyze_planted.py.text:
"""J3 attack (iv): planted exact-free filters XF(rho) on the permitted lead
shapes Z/(4 l') (K13@16, K19@64, K23@128), read through the committed
classify_family over the three lead keys. The stated NEG-path floors (XF:
0.7, 0.5, 0.5) are converted to standardised excess e_f = median over runs of
the median-over-seeds E_Sh / W of XF(floor rho). For k in 1, 2, 4 the grid rho
whose median E_Sh / W is nearest k e_f is planted (capped at rho = 1 when
k e_f exceeds XF(1)). Configurations: OWN-k (k x each shape's own floor),
FLAT-k (a common target k x max e_f at all three shapes), GROWING (1x, 2x,
4x) and DECAYING (4x, 2x, 1x); the PC-16c-like decay rho = 1, 0.7, 0.4; the
version-3 slow decay rho = 1, 0.9, 0.8; and L2-DECISIVE decays (L1 and L3
hold at all three shapes, the excess falls along the ladder). Also the
mutation test: the same configurations with L2 forced to hold.
Usage: analyze_planted.py RUNS SEED OUT"""
import json
import math
import sys

import numpy as np

import rules as R
from rules import est

FILES = {"K13": ["out/iso_K13.jsonl"], "K19": ["out/iso_K19.jsonl"],
         "K23": ["out/iso_K23_a.jsonl", "out/iso_K23_b.jsonl", "out/iso_K23_c.jsonl"]}
LEADS = (("K13", 16), ("K19", 64), ("K23", 128))
LPRIME = {"K13": 1999, "K19": 130859, "K23": 2095837}
FLOOR = {"K13": 0.7, "K19": 0.5, "K23": 0.5}
GRID = (1.0, 0.9, 0.8, 0.7, 0.6, 0.5, 0.4)


def nullsum(recs):
    return est.summarize_null([[{"G": g} for g in r["null"]] for r in recs])


def cellns(recs, name, ns):
    readings = [{"direct": {"G": r["labels"][name]["G"], "used": r["labels"][name]["used"],
                            "excluded": r["labels"][name]["excluded"],
                            "used_mass": r["labels"][name]["used_mass"], "S": r["labels"][name]["S"]},
                 "shuffle": r["labels"][name]["sh"]} for r in recs]
    return {"rows": est.seed_rows(readings, ns, ns["V"]), "null": ns}


def classify(cm, keys, xs, force_l2=False):
    v = est.classify_family(cm, keys, xs)
    if not force_l2:
        return v["verdict"], v
    per = v["per_cell"]
    if all(per[k]["L1"] and per[k]["L3"] for k in keys):
        return "LEAD", v
    if not any(p["L3"] for p in per.values()):
        return "NEG", v
    return "ART-RES", v


def main(runs, seed, out):
    pools = {sh: R.load_many(FILES[sh]) for sh in FILES}
    seeds = {sh: sorted(pools[sh][M]) for sh, M in LEADS}
    xs = [math.log2(LPRIME[s]) for s, _ in LEADS]
    rng = np.random.default_rng(seed)
    # 1. standardised excess per grid rho (median over resampled runs)
    exc = {sh: {rho: [] for rho in GRID} for sh, _ in LEADS}
    for _ in range(300):
        for sh, M in LEADS:
            recs = [pools[sh][M][int(s)] for s in rng.choice(seeds[sh], size=10, replace=False)]
            ns = nullsum(recs)
            for rho in GRID:
                c = cellns(recs, "XF@%g" % rho, ns)
                exc[sh][rho].append(est.median([r["E_Sh"] for r in c["rows"]]) / ns["W"])
    med = {sh: {rho: float(np.median(v)) for rho, v in d.items()} for sh, d in exc.items()}
    ef = {sh: med[sh][FLOOR[sh]] for sh, _ in LEADS}

    def nearest(sh, target):
        best = min(GRID, key=lambda r: abs(med[sh][r] - target))
        capped = target > med[sh][1.0]
        return best, capped

    configs = {}
    for k in (1, 2, 4):
        configs["OWN-%dx" % k] = {sh: nearest(sh, k * ef[sh]) for sh, _ in LEADS}
        common = k * max(ef.values())
        configs["FLAT-%dx (common target %.2f W)" % (k, common)] = {sh: nearest(sh, common) for sh, _ in LEADS}
    configs["GROWING 1x,2x,4x"] = {"K13": nearest("K13", ef["K13"]), "K19": nearest("K19", 2 * ef["K19"]),
                                   "K23": nearest("K23", 4 * ef["K23"])}
    configs["DECAYING 4x,2x,1x"] = {"K13": nearest("K13", 4 * ef["K13"]), "K19": nearest("K19", 2 * ef["K19"]),
                                    "K23": nearest("K23", ef["K23"])}
    configs["PC-16c-like decay rho 1, 0.7, 0.4"] = {"K13": (1.0, False), "K19": (0.7, False), "K23": (0.4, False)}
    configs["version-3 slow decay rho 1, 0.9, 0.8"] = {"K13": (1.0, False), "K19": (0.9, False), "K23": (0.8, False)}
    # L2-decisive decays: XF(1) at K13, then the smallest grid rho at K19 and K23 whose median E_Sh/W
    # still exceeds the effective LEAD floor (3 W + offset) by 1 W, with Z decreasing along the ladder
    configs["L2-decisive decay rho 1, 0.8, 0.6"] = {"K13": (1.0, False), "K19": (0.8, False), "K23": (0.6, False)}
    configs["L2-decisive decay rho 1, 0.7, 0.6"] = {"K13": (1.0, False), "K19": (0.7, False), "K23": (0.6, False)}
    configs["control: XF(1) at all three (PC-16d XF)"] = {"K13": (1.0, False), "K19": (1.0, False), "K23": (1.0, False)}
    results = {}
    for name, cfg in configs.items():
        tally = {"LEAD": 0, "NEG": 0, "ART-RES": 0, "NOT-ESTIMATED": 0}
        tally_mut = {"LEAD": 0, "NEG": 0, "ART-RES": 0, "NOT-ESTIMATED": 0}
        l1 = {sh: 0 for sh, _ in LEADS}
        l3 = {sh: 0 for sh, _ in LEADS}
        l2h = 0
        zmed = {sh: [] for sh, _ in LEADS}
        for _ in range(runs):
            cm, keys = {}, []
            for sh, M in LEADS:
                recs = [pools[sh][M][int(s)] for s in rng.choice(seeds[sh], size=10, replace=False)]
                ns = nullsum(recs)
                c = cellns(recs, "XF@%g" % cfg[sh][0], ns)
                cm[(sh, M)] = c
                keys.append((sh, M))
                zmed[sh].append(est.median([r["Z"] for r in c["rows"] if r["Z"] is not None]))
            verdict, v = classify(cm, keys, xs)
            tally[verdict] += 1
            vm, _ = classify(cm, keys, xs, force_l2=True)
            tally_mut[vm] += 1
            for (sh, M) in keys:
                l1[sh] += v["per_cell"][(sh, M)]["L1"]
                l3[sh] += v["per_cell"][(sh, M)]["L3"]
            if v["L2"] is not None and v["L2"]["holds"]:
                l2h += 1
        # exact L2 hold probability from per-seed Z pools
        zs = [[R.seed_Z(pools[sh][M][s], "XF@%g" % cfg[sh][0]) for s in seeds[sh]] for sh, M in LEADS]
        p = R.p_slope_nonneg(*zs, xs)
        results[name] = {
            "rho": {sh: cfg[sh][0] for sh, _ in LEADS},
            "capped_at_rho_1": {sh: cfg[sh][1] for sh, _ in LEADS},
            "median_E_Sh_over_W_planted": {sh: med[sh][cfg[sh][0]] for sh, _ in LEADS},
            "in_units_of_own_floor": {sh: med[sh][cfg[sh][0]] / ef[sh] for sh, _ in LEADS},
            "median_Z": {sh: float(np.median(zmed[sh])) for sh, _ in LEADS},
            "P_L1": {sh: l1[sh] / runs for sh, _ in LEADS}, "P_L3": {sh: l3[sh] / runs for sh, _ in LEADS},
            "P_L2_holds_runs": l2h / runs, "P_L2_holds_exact": 1 - R.l2_fail_prob(p),
            "verdicts": {k: v / runs for k, v in tally.items()},
            "false_NEG_rate": tally["NEG"] / runs,
            "verdicts_with_L2_forced_true (mutation)": {k: v / runs for k, v in tally_mut.items()}}
    res = {"runs": runs, "resample_seed": seed, "pool_seeds": {k: len(v) for k, v in seeds.items()},
           "median_E_Sh_over_W_by_rho": med, "stated_floor_rho": FLOOR, "floor_excess_e_f": ef,
           "configs": results}
    json.dump(res, open(out, "w"), indent=1, default=float)
    print(json.dumps(res, indent=1, default=float)[:6000])


if __name__ == "__main__":
    main(int(sys.argv[1]), int(sys.argv[2]), sys.argv[3])

analyze_gate.py.text:
"""Aggregate Part D (gates, PC-1, PC-6c) and PTM-D, and the distribution-free
PC-9 rank computation. Usage: analyze_gate.py OUT"""
import json
import sys

import numpy as np

import rules as R


def load(path):
    out = []
    try:
        for line in open(path):
            try:
                out.append(json.loads(line))
            except ValueError:
                pass
    except FileNotFoundError:
        pass
    return out


def pc9_rank_prob(trials=200000, seed=9):
    """P(median of 10 curve readings outside [q0.005, q0.995] type-1 of 200
    reference readings) when both are i.i.d. from one continuous law: the
    committed pc9_check bounds are the minimum and the 199th order statistic."""
    rng = np.random.default_rng(seed)
    fails = 0
    batch = 20000
    for _ in range(trials // batch):
        ref = np.sort(rng.random((batch, 200)), axis=1)
        cur = np.sort(rng.random((batch, 10)), axis=1)
        med = 0.5 * (cur[:, 4] + cur[:, 5])
        lo, hi = ref[:, 0], ref[:, 198]
        fails += int(((med < lo) | (med > hi)).sum())
    return fails, trials


def main(out):
    res = {}
    gates = load("out/gate.jsonl")
    by = {}
    for g in gates:
        by.setdefault(g["shape"], []).append(g)
    for sh, gs in by.items():
        fails = sum(1 for g in gs if not g["passed"])
        mk = {}
        for g in gs:
            for k, v in g["margins"].items():
                mk.setdefault(k, []).append(v)
        res["gate " + sh] = {"replicates": len(gs), "failed": fails, "upper95": R.binom_upper(fails, len(gs)),
                             "failures_seen": sorted({f for g in gs for f in g["failures"]}),
                             "margins_min": {k: float(np.min(v)) for k, v in mk.items()},
                             "margins_max": {k: float(np.max(v)) for k, v in mk.items()}}
    for name in ("pc1", "pc6c"):
        rs = load("out/%s.jsonl" % name)
        if rs:
            mk = {}
            for g in rs:
                for k, v in g["margins"].items():
                    mk.setdefault(k, []).append(v)
            fails = sum(1 for g in rs if not g["passed"])
            res[name] = {"replicates": len(rs), "failed": fails, "upper95": R.binom_upper(fails, len(rs)),
                         "failures_seen": sorted({f for g in rs for f in g["failures"]}),
                         "margins_max": {k: float(np.max([x for x in v if x is not None])) for k, v in mk.items()}}
    res["PTM-D"] = load("out/ptmd.jsonl")
    f, n = pc9_rank_prob()
    res["PC-9 distribution-free"] = {"failures": f, "trials": n, "upper95": R.binom_upper(f, n),
                                     "note": "per cell; continuous law; ties in G only make the check more lenient"}
    json.dump(res, open(out, "w"), indent=1, default=float)
    print(json.dumps(res, indent=1, default=float)[:8000])


if __name__ == "__main__":
    main(sys.argv[1])

ir12_roles.py.text:
"""IR-12 (the estimated / used-mass admission rule) for every declared role
at every declared (n, M), from the role's label marginal over UNIFORM n-bit
strings (no curve, no declared group): expected used-mass fraction
sum_ab lam_ab P(Pois(lam_ab) >= 99) / S with lam_ab = S p_a p_b (for the sum
over n_ab >= 100 of n_ab). The exact quotient e is modelled uniform on Z/4 and
independent of the inner label, except for F5xF1 where e mod 2 is the weight
parity (DF-9); F1's label is the weight bucket alone; labels of the ordinary roles are uniform windows."""
import json, math, sys
import numpy as np
sys.path.insert(0, "impl")
import families as fam

MARG = json.load(open("marginals.json"))
_lg = [math.lgamma(k + 1) for k in range(200)]

def tail99(lam):
    if lam <= 0: return 0.0
    if lam > 400: return 1.0
    s = sum(math.exp(-lam + k * math.log(lam) - _lg[k]) for k in range(99))
    return max(0.0, 1.0 - s)

def used_frac(p, S):
    p = np.asarray(p, dtype=float); p = p[p > 0]
    tot = 0.0
    for pa in p:
        lam = S * pa * p
        tot += sum(l * tail99(l) for l in lam)
    return tot / S

def S_of(M): return 1 << (128 * M * M - 1).bit_length()

def weight_marg(n):
    return np.array([math.comb(n, w) for w in range(n + 1)], dtype=float) / 2.0 ** n

def f1_marg(n, M):
    """F1's label is the weight bucket alone (alphabet M); e enters only the
    stratified shuffle, not the conditioning cells."""
    wb = fam.weight_buckets(n, M); pw = weight_marg(n)
    out = {}
    for w, p in enumerate(pw):
        out[wb[w]] = out.get(wb[w], 0.0) + p
    return list(out.values())

def f5_marg(tmarg):
    return [pt / 4 for pt in tmarg for _ in range(4)]

def f5xf1_marg(n, M):
    wb4 = fam.weight_buckets(n, M // 4); pw = weight_marg(n)
    out = {}
    for w, p in enumerate(pw):
        for hi in (0, 2):
            key = 4 * wb4[w] + (w & 1) + hi
            out[key] = out.get(key, 0.0) + p / 2
    return list(out.values())

def top_marg(n, r):
    k = "n%d_top%d" % (n, r)
    if k in MARG: return MARG[k]
    return None

ROWS = []
CELLS = {13: (16, 8), 19: (64, 16), 23: (128, 32, 16), 41: (16,)}
for n, Ms in CELLS.items():
    for M in Ms:
        S = S_of(M); r = M.bit_length() - 1
        res = {"n": n, "M": M, "S": S}
        res["F1"] = used_frac(f1_marg(n, M), S)
        res["F2/F3 (uniform window)"] = used_frac([1.0 / M] * M, S)
        t4 = top_marg(n, r) if not (n == 41 and r == 4) else MARG["n41_top4_sampled_2^20"]
        res["F4"] = used_frac(t4, S) if t4 is not None else "marginal not tabulated (n=41 r=4: >= 0.9 by the Lucas count)"
        res["F5xF1"] = used_frac(f5xf1_marg(n, M), S)
        res["F5xF2@0/F5xF3@0"] = used_frac([1.0 / M] * M, S)
        tt = top_marg(n, r - 2) if n != 41 else MARG["n41_top2"]
        res["F5xF4"] = used_frac(f5_marg(tt), S) if tt is not None else None
        ROWS.append(res)
for M in (64, 16):
    S = S_of(M)
    ROWS.append({"n": 19, "M": M, "S": S, "cell": "ordinary", "ORD-F2/F3 (uniform window)": used_frac([1.0 / M] * M, S)})
json.dump(ROWS, open("out/ir12_roles.json", "w"), indent=1)
for r in ROWS:
    print({k: (round(v, 4) if isinstance(v, float) else v) for k, v in r.items()})

structure.py.text:
import yaml, sys
p = sys.argv[1]
maxdepth = int(sys.argv[2]) if len(sys.argv) > 2 else 2
d = yaml.safe_load(open(p))
def walk(x, depth):
    if depth > maxdepth: return
    if isinstance(x, dict):
        for k, v in x.items():
            sz = len(yaml.safe_dump(v)) if v is not None else 0
            t = type(v).__name__
            extra = f' len={len(v)}' if isinstance(v, (list, dict)) else ''
            print('  '*depth + f'{k} [{t}{extra}, {sz}B]')
            walk(v, depth+1)
    elif isinstance(x, list):
        for i, v in enumerate(x[:300]):
            if isinstance(v, dict):
                ident = v.get('id') or v.get('name') or v.get('block') or ''
                sz = len(yaml.safe_dump(v))
                print('  '*depth + f'[{i}] id={ident} keys={list(v.keys())[:10]} {sz}B')
            else:
                print('  '*depth + f'[{i}] {type(v).__name__} {len(str(v))}B')
walk(d, 0)

ptmf_v3_counterfactual.py.text:
"""PTM-F: per-seed counts on the near-exact labels of the K13 shape
(Z/(4 x 1999)) and the K41 shape: EXACT readings, the revised SR-6 clause
(used-cell image outside 1, 2, 4) and the version-3 clause (whole-support image
outside 1, 2, 4 on an EXACT reading), from the Part B/C per-seed records."""
import json
import rules as R
out = {}
for shp, files in (("K13", ["out/iso_K13.jsonl"]), ("K41", ["out/iso_K41.jsonl"])):
    pool = R.load_many(files)
    for M in sorted(pool):
        for name in ("NEAR1", "NEAR2", "NEAR3", "NEARMASS", "CONC"):
            rs = [r for r in pool[M].values() if name in r["labels"]]
            if not rs:
                continue
            ex = [r["labels"][name] for r in rs if "used_image" in r["labels"][name]]
            rev = sum(1 for e in ex if len(e["used_image"]) not in (1, 2, 4))
            v3 = sum(1 for e in ex if e["image"] not in (1, 2, 4))
            out["%s@%d/%s" % (shp, M, name)] = {"seeds": len(rs), "exact_readings": len(ex),
                                                 "revised_clause_fires": rev, "version3_clause_would_fire": v3,
                                                 "per_seed_v3": v3 / len(rs)}
json.dump(out, open("out/res_ptmf_v3.json", "w"), indent=1)
for k, v in out.items():
    print(k, v)

